-- ROADMAP-DOERS-EB-1 (2026-10-28, session cluster-e-b; OWNER-NO-LOOSE-ENDS-1, charter pillars autonomy, cost, research, security): gives the doer-less RM-* roadmap issues a first
-- concrete step the code loop can place (a code-task path plus a code-anchor that occurs once in the file), lands the storage for the two measurable research metrics
-- (claim_coverage, seeded_false_claim_catch_rate), and replaces the dead probe of agent_issues 1000638 (its deliverable, docs/DETERMINISTIC-GATE-AUDIT.md, is on main).
-- No code-probe line is written for an issue whose definition of done is a measurement over time: a marker probe would close it on the first edit.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- BACKUP: bak_20261028_cluster_eb_issues
-- Rollback: UPDATE agent_issues SET description = (SELECT b.description FROM bak_20261028_cluster_eb_issues b WHERE b.id = agent_issues.id) WHERE id IN (SELECT id FROM bak_20261028_cluster_eb_issues); UPDATE remediation_contracts SET verify_probe = (SELECT b.verify_probe FROM bak_20261028_cluster_eb_contract b WHERE b.class = remediation_contracts.class), verify_transport = (SELECT b.verify_transport FROM bak_20261028_cluster_eb_contract b WHERE b.class = remediation_contracts.class) WHERE class IN (SELECT class FROM bak_20261028_cluster_eb_contract); DROP TABLE IF EXISTS paper_claims; DROP TABLE IF EXISTS seeded_claim_runs; DROP TABLE IF EXISTS ops_run_events; DELETE FROM session_records WHERE session_id = 'session-cluster-e-b-1028';

CREATE TABLE IF NOT EXISTS bak_20261028_cluster_eb_issues AS SELECT id, description FROM agent_issues WHERE id IN (1000637, 1000639, 1000640, 1000641, 1000642, 1000644, 1000648, 1000649, 1000650, 1000651, 1000652, 1000653, 1000664, 1000665, 1000707, 1000709);
CREATE TABLE IF NOT EXISTS bak_20261028_cluster_eb_contract AS SELECT class, verify_probe, verify_transport FROM remediation_contracts WHERE class = 'issue-1000638';

-- Storage for RM-CLAIMS-LEDGER-1 (1000664) and RM-SEEDED-CLAIM-HARNESS-1 (1000665); read by scripts/bp26_claims.py and scripts/bp26_seeded.py.
CREATE TABLE IF NOT EXISTS paper_claims (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL, version TEXT, claim_text TEXT NOT NULL, claim_kind TEXT, source_ref TEXT, verification_state TEXT NOT NULL DEFAULT 'unverified', verified_by TEXT, published_at TEXT NOT NULL DEFAULT (datetime('now')), verified_at TEXT, created_at TEXT NOT NULL DEFAULT (datetime('now')));
CREATE INDEX IF NOT EXISTS idx_paper_claims_published ON paper_claims (published_at);
CREATE INDEX IF NOT EXISTS idx_paper_claims_slug ON paper_claims (slug, version);
CREATE TABLE IF NOT EXISTS seeded_claim_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, ts TEXT NOT NULL DEFAULT (datetime('now')), seed_id TEXT NOT NULL, gate TEXT NOT NULL, caught INTEGER NOT NULL, detail TEXT);
CREATE INDEX IF NOT EXISTS idx_seeded_claim_runs_ts ON seeded_claim_runs (ts);
-- Storage for RM-TRACE-FOLD-1 (1000650): append-only event ledger per long qnfo-ops run; the fold is a pure function in qnfo-ops.
CREATE TABLE IF NOT EXISTS ops_run_events (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id TEXT NOT NULL, seq INTEGER NOT NULL, ts TEXT NOT NULL DEFAULT (datetime('now')), kind TEXT NOT NULL, tool TEXT, args_sha TEXT, ok INTEGER, bytes_out INTEGER, detail TEXT);
CREATE INDEX IF NOT EXISTS idx_ops_run_events_run ON ops_run_events (run_id, seq);

UPDATE metric_registry SET source_of_truth = 'qnfo-audit.paper_claims (atomic-claims ledger, RM-CLAIMS-LEDGER-1), read by scripts/bp26_claims.py [BP26]' WHERE metric = 'claim_coverage' AND source_of_truth LIKE '%to build%';
UPDATE metric_registry SET source_of_truth = 'qnfo-audit.seeded_claim_runs, written by scripts/seeded_claim_harness.mjs through scripts/bp26_seeded.py [BP26]' WHERE metric = 'seeded_false_claim_catch_rate' AND source_of_truth LIKE '%to build%';

-- 1000638: the deliverable exists (docs/DETERMINISTIC-GATE-AUDIT.md lists 21 decision points, names the check for each MODEL-ONLY row, and migrations/2026-10-28-gate-audit-issues.sql filed the follow-ups).
UPDATE remediation_contracts SET verify_probe = '{"paths": ["docs/DETERMINISTIC-GATE-AUDIT.md"], "contains": "## Recommended deterministic check for each MODEL-ONLY row"}', verify_transport = 'code-read', next_due_at = datetime('now') WHERE class = 'issue-1000638';

